import{_ as t,c as l,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"读易举要","description":"读易举要 - 读易举要","frontmatter":{"title":"读易举要","description":"读易举要 - 读易举要"},"headers":[],"relativePath":"zh/classics/juyao/001.md","filePath":"zh/classics/juyao/001.md"}'),r={name:"zh/classics/juyao/001.md"};function o(c,a,i,p,d,u){return s(),l("div",null,[...a[0]||(a[0]=[e("h1",{id:"读易举要",tabindex:"-1"},[n("读易举要 "),e("a",{class:"header-anchor",href:"#读易举要","aria-label":"Permalink to “读易举要”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：",-1),e("p",null,"读易举要四卷，宋俞琰撰。是书文渊阁书目、焦竑经籍志、朱睦桔授经图皆著于录。然外间傅本殊稀，故朱彝尊经义考亦云「未见」。今惟永乐大典尚散见于各韵之中，可以采辑。谨裒合编次，仍定为四卷。考琰之集说，以朱子为宗，而此书论刚柔往来，则以两卦反对见义例，以泰、否二卦彖辞，较朱子卦变之说更近自然。其易图多本邵子，而此书论象数之学，则驳张行成以「元亨利贞」为周易起数于四之证，盖不为苟同者。至于田畴，谓积乾坤屯蒙、需、讼之策，至于师而六军之数皆全。史璇谓革居四十九，应大衍之数，故云天地革而四时成；节居六十而甲子一周，故云天地节而四时成。皆以偶合之见，窥圣人作易之意。琰顾取之，则殊非本旨。然琰于易苦思力索，积平生之力为之，意所独契，亦往往超出前人。所列诸家著述，虽多本于晁公武、陈振孙两家，而名字爵里间有异同，亦可资考证，固宜与所撰集说并行也。琰别有六十四卦图、易图合璧联珠、易图纂要诸书，旧与此书合刻。修永乐大典之时，割裂庞杂，淆其端绪。惟八分为十六，十六分为三十二两图犹标俞琰纂图之目，其余诸图尽冒读易举要之名，合并为一，殊为瞀乱。今悉考订汰除，以还其旧焉。乾隆四十六年九月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。钦定四库全书读易举要目录：卷一易为卜筮之书卦画取象占用阴阳老少占用贞悔卦爻之占辞象占所称象辞占辞之异卦变刚来柔来上下图卷二易中杂例卦义八卦主爻图十二卦主爻图卦之主爻乘承比应辞韵之叶卷三论象数之学",-1),e("p",null,"河图洛书之附会， 附图三， 卦气之附会纳甲之附会三易易字义卦象彖爻字义重卦之人名卦之人作彖辞爻辞之人卷四，",-1),e("p",null,"经分上下二篇， 附图三， 十翼之目古文周易十二篇汉儒相传之易魏晋以后唐宋以来诸家著述",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
